TAGS = {0x010F: "Make", 0x0110: "Model", 0x0132: "DateTime"}

def read_jpeg_exif(path: Path) -> dict[str, str]:
    buf = path.read_bytes()
    if buf[:2] != b"\xff\xd8":
        raise ValueError("Not a JPEG file")
    pos = 2
    while pos + 4 <= len(buf) and buf[pos] == 0xFF:
        marker = buf[pos + 1]
        if marker == 0xDA:
            break
        (seg_len,) = struct.unpack_from(">H", buf, pos + 2)
