                return {}
            magic, ifd_off = struct.unpack_from(f"{endian}HI", tiff, 2)
            if magic != 0x002A or ifd_off + 2 > len(tiff):
                return {}
            (count,) = struct.unpack_from(f"{endian}H", tiff, ifd_off)
            out: dict[str, str] = {}
            for i in range(count):
                e_off = ifd_off + 2 + i * 12
                if e_off + 12 > len(tiff):
                    break
                tag, fmt, ncomp, val_off = struct.unpack_from(f"{endian}HHII", tiff, e_off)
                if tag in TAGS and fmt == 2:
                    raw = tiff[e_off + 8 : e_off + 8 + ncomp] if ncomp <= 4 else tiff[val_off : val_off + ncomp]
