        for i in range(e_shnum)
        if e_shoff + (i + 1) * e_shentsize <= len(buf)
    ]
    imports: list[str] = []
    for sh in shdrs:
        sh_type, sh_off, sh_sz, sh_link, sh_entsz = sh[1], sh[4], sh[5], sh[6], sh[9]
        if sh_type != SHT_DYNSYM or sh_link >= len(shdrs):
