        str_off, str_sz = shdrs[sh_link][4], shdrs[sh_link][5]
        dynstr = buf[str_off : str_off + str_sz]
        step = sh_entsz or 24
        for pos in range(sh_off, sh_off + sh_sz, step):
            if pos + 24 > len(buf):
