            st_name, _info, _other, st_shndx, _val, _sz = struct.unpack_from(f"{end}IBBHQQ", buf, pos)
            if st_shndx == SHN_UNDEF and st_name < len(dynstr):
                end_nul = dynstr.find(b"\x00", st_name)
                sym = dynstr[st_name : end_nul if end_nul != -1 else len(dynstr)].decode("utf-8", errors="replace")
                if sym:
                    imports.append(sym)
    return sorted(set(imports))

if __name__ == "__main__":
    if len(sys.argv) != 2:
        sys.exit(f"Usage: {sys.argv[0]} <elf64_binary>")
