```python
#!/usr/bin/env python3

def mat_inv_mod(mat: list[list[int]], p: int) -> list[list[int]]:
    n = len(mat)
    if n == 0 or any(len(row) != n for row in mat):
        raise ValueError("Matrix must be non-empty and square")
    aug = [
        [(mat[r][c] % p) for c in range(n)] + [1 if r == c else 0 for c in range(n)]
        for r in range(n)
    ]
    for col in range(n):
        piv = next((r for r in range(col, n) if aug[r][col] % p != 0), None)
        if piv is None:
            raise ValueError("Matrix is singular modulo p")
        aug[col], aug[piv] = aug[piv], aug[col]
        inv_piv = pow(aug[col][col], -1, p)
        aug[col] = [(v * inv_piv) % p for v in aug[col]]
        for r in range(n):
            if r != col and aug[r][col] != 0:
                factor = aug[r][col]
                aug[r] = [(aug[r][k] - factor * aug[col][k]) % p for k in range(2 * n)]
    return [row[n:] for row in aug]

if __name__ == "__main__":
    p_mod = 97
    A = [[3, 10, 20], [20, 9, 17], [9, 4, 17]]
    invA = mat_inv_mod(A, p_mod)
    ident = [
        [sum(A[i][k] * invA[k][j] for k in range(3)) % p_mod for j in range(3)]
        for i in range(3)
    ]
    assert ident == [[1, 0, 0], [0, 1, 0], [0, 0, 1]]
    print("Inverse mod 97:", invA)
```

