#!/usr/bin/env python3
import struct

MASK32 = 0xFFFFFFFF

def rol32(val: int, shift: int) -> int:
    shift &= 31
    return ((val << shift) | ((val & MASK32) >> (32 - shift))) & MASK32

def round_fn(half: int, subkey: int) -> int:
    mixed = (rol32(half ^ subkey, 7) + 0x9E3779B9) & MASK32
    return rol32(mixed, 13) ^ subkey

def feistel_encrypt(block8: bytes, subkeys: list[int]) -> bytes:
    left, right = struct.unpack(">II", block8)
    for k in subkeys:
        left, right = right, left ^ round_fn(right, k)
    return struct.pack(">II", left, right)

def feistel_decrypt(block8: bytes, subkeys: list[int]) -> bytes:
    left, right = struct.unpack(">II", block8)
    for k in reversed(subkeys):
        left, right = right ^ round_fn(left, k), left
    return struct.pack(">II", left, right)

