#!/usr/bin/env python3
import struct
import sys
from pathlib import Path

SHT_NOTE = 7
NT_GNU_BUILD_ID = 3

def align4(n: int) -> int:
    return (n + 3) & ~3

def read_build_id(path: Path) -> str | None:
    buf = path.read_bytes()
    if len(buf) < 64 or buf[:4] != b"\x7fELF" or buf[4] != 2:
        raise ValueError("Expected ELF64 binary")
    end = "<" if buf[5] == 1 else ">"
    (e_shoff,) = struct.unpack_from(f"{end}Q", buf, 40)
    e_shentsize, e_shnum = struct.unpack_from(f"{end}HH", buf, 58)
    for i in range(e_shnum):
        sh_off_hdr = e_shoff + i * e_shentsize
        if sh_off_hdr + 64 > len(buf):
            break
        sh = struct.unpack_from(f"{end}IIQQQQIIQQ", buf, sh_off_hdr)
        if sh[1] != SHT_NOTE:
            continue
        pos, end_pos = sh[4], min(sh[4] + sh[5], len(buf))
        while pos + 12 <= end_pos:
            namesz, descsz, ntype = struct.unpack_from(f"{end}III", buf, pos)
            name_off = pos + 12
            desc_off = name_off + align4(namesz)
            next_pos = desc_off + align4(descsz)
            if next_pos > end_pos:
                break
            if ntype == NT_GNU_BUILD_ID and buf[name_off : name_off + namesz] == b"GNU\x00":
                return buf[desc_off : desc_off + descsz].hex()
            pos = next_pos
    return None

if __name__ == "__main__":
    if len(sys.argv) != 2:
        sys.exit(f"Usage: {sys.argv[0]} <elf64_file>")
    print("Build-ID:", read_build_id(Path(sys.argv[1])) or "<not found>")
