#!/usr/bin/env python3
import sys
from datetime import datetime, timezone
from pathlib import Path

def lint_security_txt(text: str) -> list[str]:
    issues: list[str] = []
    contacts: list[str] = []
    expires: list[str] = []
    for lineno, raw in enumerate(text.splitlines(), 1):
        line = raw.strip()
        if not line or line.startswith("#") or line.startswith("-----"):
            continue
        if ":" not in line:
            continue
        key, val = [x.strip() for x in line.split(":", 1)]
        low = key.lower()
        if low == "contact":
            contacts.append(val)
            if not val.lower().startswith(("mailto:", "https://", "tel:")):
                issues.append(f"line {lineno}: insecure or invalid Contact URI '{val}'")
        elif low == "expires":
            expires.append(val)
    if not contacts:
        issues.append("missing mandatory Contact field")
    if len(expires) != 1:
        issues.append(f"expected exactly 1 Expires field, found {len(expires)}")
    else:
        dt = datetime.fromisoformat(expires[0].replace("Z", "+00:00")).astimezone(timezone.utc)
        if dt <= datetime.now(timezone.utc):
            issues.append(f"Expires timestamp {dt.isoformat()} is in the past")
    return issues

if __name__ == "__main__":
    if len(sys.argv) != 2:
        sys.exit(f"Usage: {sys.argv[0]} <security.txt>")
    errs = lint_security_txt(Path(sys.argv[1]).read_text(encoding="utf-8"))
    for e in errs:
