#!/usr/bin/env python3
import glob
import os
import stat
import sys
from pathlib import Path

def parse_ld_conf(conf_path: Path, seen: set[Path] | None = None) -> list[str]:
    seen = seen or set()
    real = conf_path.resolve()
    if real in seen or not real.is_file():
        return []
    seen.add(real)
    dirs: list[str] = []
    for raw in real.read_text(encoding="utf-8", errors="replace").splitlines():
        line = raw.split("#", 1)[0].strip()
        if not line:
            continue
        if line.startswith("include "):
            pat = line.split(None, 1)[1].strip()
            if not pat.startswith("/"):
                pat = str(real.parent / pat)
            for sub in sorted(glob.glob(pat)):
                dirs.extend(parse_ld_conf(Path(sub), seen))
        else:
            dirs.append(line)
    return dirs

def audit_lib_dirs(dirs: list[str]) -> list[str]:
    findings: list[str] = []
    for d in dirs:
        if not d.startswith("/"):
            findings.append(f"relative library path: '{d}'")
            continue
        if not os.path.isdir(d):
            continue
        st = os.stat(d)
        if st.st_uid != 0:
            findings.append(f"non-root owner uid={st.st_uid} on '{d}'")
        if st.st_mode & (stat.S_IWGRP | stat.S_IWOTH):
            findings.append(f"writable mode {oct(stat.S_IMODE(st.st_mode))} on '{d}'")
    return findings

if __name__ == "__main__":
    ld_dirs = parse_ld_conf(Path("/etc/ld.so.conf"))
    if len(sys.argv) == 2 and sys.argv[1]:
        ld_dirs.extend(sys.argv[1].split(":"))
    for issue in audit_lib_dirs(ld_dirs):
        print(f"[WARN] {issue}")
