#!/usr/bin/env python3
import re

def parse_cpe23(cpe: str) -> dict[str, str]:
    parts = re.split(r"(?<!\\):", cpe.strip())
    if len(parts) < 6 or parts[0] != "cpe" or parts[1] != "2.3":
        raise ValueError(f"Invalid CPE 2.3 string: {cpe}")
    return {"part": parts[2], "vendor": parts[3], "product": parts[4], "version": parts[5]}

def ver_tuple(v: str) -> tuple[int, ...]:
