#[derive(Debug, PartialEq)]
struct TlvRecord<'a> {
    tag: u8,
    value: &'a [u8],
}

fn parse_tlv_stream(buf: &[u8]) -> Result<Vec<TlvRecord<'_>>, &'static str> {
    let mut out = Vec::new();
    let mut pos: usize = 0;
    while pos < buf.len() {
        let hdr_end = pos.checked_add(3).ok_or("header offset overflow")?;
        let hdr = buf.get(pos..hdr_end).ok_or("truncated TLV header")?;
        let tag = hdr[0];
        let len = u16::from_be_bytes([hdr[1], hdr[2]]) as usize;
        let val_end = hdr_end.checked_add(len).ok_or("payload length overflow")?;
        let value = buf.get(hdr_end..val_end).ok_or("truncated TLV value")?;
        out.push(TlvRecord { tag, value });
        pos = val_end;
    }
    Ok(out)
}

fn main() {
    let pkt = [0x01u8, 0x00, 0x03, b'A', b'C', b'K', 0x02, 0x00, 0x01, 0x7f];
    let recs = parse_tlv_stream(&pkt).unwrap();
