import re
import sys
from pathlib import Path

BAD_ENV_RE = re.compile(r"env_keep\s*\+?=.*\b(LD_PRELOAD|LD_LIBRARY_PATH|PYTHONPATH)\b")
NOPASS_ALL_RE = re.compile(r"NOPASSWD:\s*ALL\b")
CMD_WILDCARD_RE = re.compile(r"=\s*(?:\([^)]*\)\s*)?(?:NOPASSWD:\s*)?/.*\*")

def lint_sudoers(text: str) -> list[str]:
    findings: list[str] = []
    logical = ""
    for idx, raw in enumerate(text.splitlines(), 1):
        stripped = raw.split("#", 1)[0].rstrip()
        if stripped.endswith("\\"):
            logical += stripped[:-1] + " "
            continue
        line = (logical + stripped).strip()
        logical = ""
        if not line:
