        if CMD_WILDCARD_RE.search(line):
            findings.append(f"line {idx}: wildcard '*' in sudo command specification: {line}")
    return findings

if __name__ == "__main__":
    if len(sys.argv) != 2:
        sys.exit(f"Usage: {sys.argv[0]} <sudoers_file>")
    for msg in lint_sudoers(Path(sys.argv[1]).read_text(encoding="utf-8")):
