#!/usr/bin/env python3
import struct
import sys
from datetime import datetime, timezone
from pathlib import Path

EPOCH_AS_FILETIME = 116444736000000000

def filetime_to_iso(ft: int) -> str:
    if ft <= EPOCH_AS_FILETIME:
        return "<unset>"
    unix_s = (ft - EPOCH_AS_FILETIME) / 10_000_000.0
    return datetime.fromtimestamp(unix_s, tz=timezone.utc).isoformat()

def parse_lnk_header(path: Path) -> None:
