    link_flags, file_attrs, ctime, atime, wtime, fsize = struct.unpack_from("<IIQQQI", hdr, 0x14)
    print(f"LinkFlags    : 0x{link_flags:08x} FileAttrs=0x{file_attrs:08x} TargetSize={fsize}")
    print(f"CreationTime : {filetime_to_iso(ctime)}")
    print(f"AccessTime   : {filetime_to_iso(atime)}")
    print(f"WriteTime    : {filetime_to_iso(wtime)}")

if __name__ == "__main__":
    if len(sys.argv) != 2:
