```python
#!/usr/bin/env python3

POLY = 0x1021

def crc16_bitwise(data: bytes, init: int = 0xFFFF) -> int:
    crc = init & 0xFFFF
    for b in data:
        crc ^= b << 8
        for _ in range(8):
            crc = ((crc << 1) ^ POLY) & 0xFFFF if (crc & 0x8000) else (crc << 1) & 0xFFFF
    return crc

def build_crc16_table() -> list[int]:
    return [crc16_bitwise(bytes([i]), init=0) for i in range(256)]

CRC16_TABLE = build_crc16_table()

def crc16_fast(data: bytes, init: int = 0xFFFF) -> int:
    crc = init & 0xFFFF
    for b in data:
        idx = ((crc >> 8) ^ b) & 0xFF
        crc = ((crc << 8) ^ CRC16_TABLE[idx]) & 0xFFFF
    return crc

if __name__ == "__main__":
    vec = b"123456789"
    assert crc16_bitwise(vec) == 0x29B1
    assert crc16_fast(vec) == 0x29B1
    print(f"CRC16-CCITT-FALSE('123456789') = 0x{crc16_fast(vec):04x}")
