#!/usr/bin/env python3
import sys
from pathlib import Path

REQUIRED_OPTS = {"nosuid", "nodev", "noexec"}
TEMP_MOUNTS = ("/tmp", "/var/tmp", "/dev/shm")

def audit_fstab(path: Path) -> list[str]:
    mounts: dict[str, set[str]] = {}
    for raw in path.read_text(encoding="utf-8", errors="replace").splitlines():
        line = raw.split("#", 1)[0].strip()
        if not line:
            continue
        cols = line.split()
        if len(cols) >= 4:
            mounts[cols[1]] = {o.strip() for o in cols[3].split(",") if o.strip()}
    findings: list[str] = []
    for mp in TEMP_MOUNTS:
        if mp not in mounts:
            findings.append(f"{mp}: no dedicated mount entry in fstab")
            continue
        missing = sorted(REQUIRED_OPTS - mounts[mp])
        if missing:
            findings.append(f"{mp}: missing mount options {missing}")
    return findings

if __name__ == "__main__":
    target = Path(sys.argv[1]) if len(sys.argv) == 2 else Path("/etc/fstab")
    errs = audit_fstab(target)
    for e in errs:
        print(f"[WARN] {e}")
    sys.exit(1 if errs else 0)
