```python
#!/usr/bin/env python3

class MontgomeryDomain:
    def __init__(self, modulus: int) -> None:
        if modulus < 3 or modulus % 2 == 0:
            raise ValueError("Modulus must be an odd integer >= 3")
        self.n = modulus
        self.k = modulus.bit_length()
        self.r = 1 << self.k
        self.mask = self.r - 1
        self.n_prime = (-pow(self.n, -1, self.r)) & self.mask
        self.r2 = (self.r * self.r) % self.n

    def reduce(self, t: int) -> int:
        m = ((t & self.mask) * self.n_prime) & self.mask
        u = (t + m * self.n) >> self.k
        return u - self.n if u >= self.n else u

    def to_mont(self, x: int) -> int:
        return self.reduce((x % self.n) * self.r2)

    def from_mont(self, x_bar: int) -> int:
        return self.reduce(x_bar)

    def mul(self, a_bar: int, b_bar: int) -> int:
        return self.reduce(a_bar * b_bar)

if __name__ == "__main__":
    dom = MontgomeryDomain(1000000007)
    a, b = 123456789, 987654321
    prod = dom.from_mont(dom.mul(dom.to_mont(a), dom.to_mont(b)))
    assert prod == (a * b) % 1000000007
    print(f"Montgomery product verified: {prod}")
```

