#!/usr/bin/env python3
import struct
import sys
from pathlib import Path

BLOCK_NAMES = {0x0A0D0D0A: "SHB", 1: "IDB", 3: "SPB", 6: "EPB"}

def walk_pcapng(path: Path) -> int:
    buf = path.read_bytes()
    off, end, bad = 0, "<", 0
    while off + 12 <= len(buf):
        (btype_le,) = struct.unpack_from("<I", buf, off)
        if btype_le == 0x0A0D0D0A:
            if off + 12 > len(buf):
                break
            bom = buf[off + 8 : off + 12]
            end = "<" if bom == b"\x4d\x3c\x2b\x1a" else ">" if bom == b"\x1a\x2b\x3c\x4d" else end
        btype, total_len = struct.unpack_from(f"{end}II", buf, off)
        if total_len < 12 or total_len % 4 != 0 or off + total_len > len(buf):
            print(f"[!] Invalid block length={total_len} at 0x{off:x}")
            return bad + 1
        (trailer_len,) = struct.unpack_from(f"{end}I", buf, off + total_len - 4)
        status = "OK" if trailer_len == total_len else "TRAILER_MISMATCH"
        if status != "OK":
            bad += 1
        print(f"0x{off:08x} type={BLOCK_NAMES.get(btype, hex(btype)):<5} len={total_len} [{status}]")
        off += total_len
    return bad

if __name__ == "__main__":
    if len(sys.argv) != 2:
        sys.exit(f"Usage: {sys.argv[0]} <capture.pcapng>")
    sys.exit(1 if walk_pcapng(Path(sys.argv[1])) else 0)
